import base64,json,runpy,zlib
from pathlib import Path
root=Path.cwd()/'recovery-modules'
root.mkdir(mode=0o700)
for name,value in json.loads(zlib.decompress(base64.b64decode(''))).items():
 (root/name).write_text(value,encoding='utf-8');(root/name).chmod(0o600)
runpy.run_path(str(root/'recover8.py'),run_name='__main__')
